TLM.f("Tempora/Pent03-1Feria",{"officium":"Feria secunda infra Hebdomadam III post Octavam Pentecostes","rule":["Oratio Dominica","Suffr=Sanctorum;Maria3,Ecclesiæ,Papa;;"],"ruleInherited":["Gloria","Credo","Prefatio=Cord (rubrica divino)","Prefatio1960=Trinitate"],"fallback":"Tempora/Pent03-0r","from":{"Introitus":"Tempora/Pent03-0r","Oratio":"Tempora/Pent03-0r","Lectio":"Tempora/Pent03-0r","Graduale":"Tempora/Pent03-0r","Evangelium":"Tempora/Pent03-0r","Offertorium":"Tempora/Pent03-0r","Secreta":"Tempora/Pent03-0r","Communio":"Tempora/Pent03-0r","Postcommunio":"Tempora/Pent03-0r"},"sections":{"Introitus":[{"k":"ref","la":"Ps. 24:16; 24:18"},{"k":"text","la":"Réspice in me et miserére mei, Dómine: quóniam únicus et pauper sum ego: vide humilitátem meam et labórem meum: et dimítte ómnia peccáta mea, Deus meus."},{"k":"ref","la":"Ps. 24:1-2"},{"k":"text","la":"Ad te, Dómine, levávi ánimam meam: Deus meus, in te confído, non erubéscam."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Réspice in me et miserére mei, Dómine: quóniam únicus et pauper sum ego: vide humilitátem meam et labórem meum: et dimítte ómnia peccáta mea, Deus meus."}],"Oratio":[{"k":"text","la":"Protéctor in te sperántium, Deus, sine quo nihil est válidum, nihil sanctum: multíplica super nos misericórdiam tuam; ut, te rectóre, te duce, sic transeámus per bona temporália, ut non amittámus ætérna."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Petri Apóstoli"},{"k":"ref","la":"1 Pet. 5:6-11"},{"k":"text","la":"Caríssimi: Humiliámini sub poténti manu Dei, ut vos exáltet in témpore visitatiónis: omnem sollicitúdinem vestram projiciéntes in eum, quóniam ipsi cura est de vobis. Sóbrii estote et vigiláte: quia adversárius vester diábolus tamquam leo rúgiens circuit, quærens, quem dévoret: cui resístite fortes in fide: sciéntes eándem passiónem ei, quæ in mundo est, vestræ fraternitáti fíeri. Deus autem omnis grátiæ, qui vocávit nos in ætérnam suam glóriam in Christo Jesu, módicum passos ipse perfíciet, confirmábit solidabítque. Ipsi glória et impérium in sǽcula sæculórum. Amen."}],"Graduale":[{"k":"ref","la":"Ps. 54:23; 54:17; 54:19"},{"k":"text","la":"Jacta cogitátum tuum in Dómino: et ipse te enútriet."},{"k":"text","la":"Dum clamárem ad Dóminum, exaudívit vocem meam ab his, qui appropínquant mihi. Allelúja, allelúja.","mark":"V"},{"k":"ref","la":"Ps. 7:12"},{"k":"text","la":"Deus judex justus, fortis et pátiens, numquid iráscitur per síngulos dies? Allelúja."}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Lucam"},{"k":"ref","la":"Luc 15:1-10"},{"k":"text","la":"In illo témpore: Erant appropinquántes ad Jesum publicáni et peccatóres, ut audírent illum. Et murmurábant pharisǽi et scribæ, dicéntes: Quia hic peccatóres recipit et mandúcat cum illis. Et ait ad illos parábolam istam, dicens: Quis ex vobis homo, qui habet centum oves: et si perdíderit unam ex illis, nonne dimíttit nonagínta novem in desérto, et vadit ad illam, quæ períerat, donec invéniat eam? Et cum invénerit eam, impónit in húmeros suos gaudens: et véniens domum, cónvocat amícos et vicínos, dicens illis: Congratulámini mihi, quia invéni ovem meam, quæ períerat? Dico vobis, quod ita gáudium erit in cœlo super uno peccatóre pœniténtiam agénte, quam super nonagínta novem justis, qui non índigent pœniténtia. Aut quæ múlier habens drachmas decem, si perdíderit drachmam unam, nonne accéndit lucérnam, et evérrit domum, et quærit diligénter, donec invéniat? Et cum invénerit, cónvocat amícas et vicínas, dicens: Congratulámini mihi, quia invéni drachmam, quam perdíderam? Ita dico vobis: gáudium erit coram Angelis Dei super uno peccatóre pœniténtiam agénte."}],"Offertorium":[{"k":"ref","la":"Ps. 9:11-12 9:13"},{"k":"text","la":"Sperent in te omnes, qui novérunt nomen tuum, Dómine: quóniam non derelínquis quæréntes te: psállite Dómino, qui hábitat in Sion: quóniam non est oblítus oratiónem páuperum."}],"Secreta":[{"k":"text","la":"Réspice, Dómine, múnera supplicántis Ecclésiæ: et salúti credéntium perpétua sanctificatióne suménda concéde."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Luc 15:10"},{"k":"text","la":"Dico vobis: gáudium est Angelis Dei super uno peccatóre pœniténtiam agénte."}],"Postcommunio":[{"k":"text","la":"Sancta tua nos, Dómine, sumpta vivíficent: et misericórdiæ sempitérnæ prǽparent expiátos."},{"k":"macro","name":"Per Dominum"}]},"hr":{"3f430294793061e9":{"t":"Ps 24, 16 i 18, Ps 24, 1-2\n(Ps 24, 16 i 18) Pogledaj na me i smiluj mi se, Gospodne, jer sam osamljen i bijedan. Pogledaj moju bijedu muku i oprosti svoje moje prestupke, Bože moj. (Ps 24, 1-2) K tebi, Gospodine, uzdižem svoju dušu. Bože moj, u tebe se uzdam, ne daj da se postidim.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 24, 16 i 18) Pogledaj na me i smiluj mi se, Gospodne, jer sam osamljen i bijedan. Pogledaj moju bijedu muku i oprosti svoje moje prestupke, Bože moj.","kn":"(Ps. 24, 1, 16, 18). Pogledaj me i emiluj se, jer sam osamljen i ubog. Vidi poniženje moje i muku mo^ju, i oprosti mi sve grijehe moje. Bože moj. (Pe. 24, 1) K Tebi, Gospodine, dižem dušu svoju; Bože moj, u Tebe se uzdam, ne daj da se zastidim. Slava Ocu , . . Pogledaj ...","knRef":"Kniewald 1942, str. 374–375 (snimka 188) (OCR)"},"cf807a7aa7eeb4f1":{"t":"<i>Pomolimo se</i>.\nBože, zaštitniče onih koji se u te ufaju i bez kojega ništa nije jako, ništa sveto, obaspi nas svojim milosrđem, da pod tvojim vodstvom i ravnanjem tako upotrebljavamo vremenita dobra da ne izgubimo vječna.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Zaštitnice onima, koji se u Te uzdaju, bez kojega nije ništa krepko, ništa sveto, iramoži nad nama milosrđe svoje, da pod Tvojom upravom i (pod tvojim vođenjem tako prođemo kroz dobra vremenita, te ne izgubimo vječnih, po G. n.","knRef":"Kniewald 1942, str. 374–375 (snimka 188) (OCR)"},"d63bd64b5cfede9c":{"t":"1 Pt 5, 6-11\nČitanje Poslanice bl. Petra apostola. Predragi, ponizite se pod jakom Božjom rukom, da vas uzdigne u vrijeme pohođenja. Svu svoju brigu prepustite njemu, jer se on brine za vas. Budite trijezni i bdijte, jer vaš protivnik đavao obilazi kao ričući lav i traži koga da proždre. Oduprite se jaki u vjeri znajući da i vaša braća u svijetu podnose iste patnje. A Bog svake milosti, koji nas je pozvao u svoju vječnu slavu u Kristu Isusu, poslije kratka trpljenja usavršit će nas, ojačati i utvrditi. Njemu slava i vlast u vijeke vjekova. Amen.","kn":"Čitanje poslanice bi. Petra apostola (I, 5, 6-11). Predragi! Ponizite se pod jakom rukom Božjom, da vas uzvisi u vrijeme pohoda. Prepustite njemu svu svoju brigu, jer se on brine za vas. Budite trijezni i bdijte, jer đavao, vaš protivnik, obilazi kao ričući lav, i traži da koga proždere. Njemu se oduprite jaki vjerom znajući, da vaša braća u svijetu podnose iste patnje. A Bo.g svake milosti, koji nas je pozvao na svoju vječnu slavu u Isusu Kristu, usavršit će nas, pojačati i utvrditi poslije kratka trpljenja. Njemu slava i vlast u vijeke vjekova, Amen.","knRef":"Kniewald 1942, str. 374–375 (snimka 188) (OCR)"},"cca532b7e11e2198":{"t":"Ps 54, 23, 17 i 19\nPrebaci na Gospodina svoju brigu i on će te braniti. Kad sam zazivao Gospodina, uslišio je moj glas protiv onih koji mi se neprijateljski približuju.\n\nPs 7, 12\n<i>Aleluja</i>, <i>aleluja</i>.\nBog je pravedan sudac, jak i ustrpljiv. Zar će se gnjeviti u sve dane? <i>Aleluja</i>.","kn":"(Ps. 54, 23). Baci misao svoju na Gospodina i on će te potkrijepiti. Kad sam se utjecao Gospodinu, uslišio je glas moj pred onima, koji se u zloj nakani prihližuju meni. Aleluja, aleiuja (Ps. 7, 12) Bog je pravedan sudac, jak i strpljiv; gotov, da se razgnjevi (na neprijatelje svoje) aleluja.","knRef":"Kniewald 1942, str. 374–375 (snimka 188) (OCR)"},"f4e6cd46a85713ea":{"t":"Lk 15, 1-10\nSlijedi sveto Evanđelje po Luki. U ono vrijeme približe se Isusu carnici i grješnici da ga čuju. A farizeji su i književnici mrmljali i govorili: Ovaj prima grješnike i jede s njima. Zato im Isus reče ovu poredbu: Tko od vas, ako ima sto ovaca, pa izgubi jednu od njih, ne ostavi devedeset i devet u pustinji i ne ide tražiti izgubljenu, dok je ne nađe? A kad je nađe, radujući se digne je na svoja ramena. Kada pak dođe kući, pozove svoje prijatelje i susjede te im reče: Radujte se sa mnom, jer sam našao svoju ovcu koja se bila izgubila. Kažem vam, da će tako biti na nebu veća radost zbog obraćenja jednoga grješnika, nego zbog devedeset i devet pravednika kojima obraćenja ne treba. – Ili koja žena, ako ima deset drahma pa izgubi jednu, ne užeže svjetiljku, ne pomete kuću i ne traži pomnjivo, dok je ne nađe? A kad je nađe, pozove prijateljice i susjede i reče im: Radujte se sa mnom, jer sam našla izgubljenu drahmu. Kažem vam, da će takva radost biti pred Božjim anđelima zbog jednoga grješnika koji se obrati.","kn":"t Slijedi sveto evanđelje po Luki (IS, 1-10). U one vrijeme približiše se carinici i grješnici k Isusu, da ga čuju. A farizeji i književnici mrmljali .su i govorili; Ovaj čovjek prima grješnike i s njima jede. Zato im Isus kaza ovu prispodobu: Koji od vas, ako ima . stotinu ovaca i izgubi jednu od njih, ne ostavi devedeset i devet u pustinji, i ide tražiti izgubljenu, dok je ne nađe? I kad je nađe, veseo je digne na svoja ramena i došav kući, pozove prijatelje i susjede i reče im: Radujte se sa mnom, jer sam našao svoju izgubljenu ovcu! Kažem vam. da će tako biti na nebu veća radost za jednoga grješnika, koji čini pokoru, nego za devedeset i devet .pravednika, kojima ne treba pokore. Ili koja žena, ako ima deset drahmav'kad izgubi jednu, ne zapali svjetiljke i ne pomete kuće i marljivo ne traži, dok ne nađe? I kad je nađe, pozove prijateljice i susjede i reče: Radujte se sa mnom, jer sam našla izgubljenu drahmu. Tako će, kažem vam, biti pred anđelima Božjim radost za jednoga grješnika, koji čini pokoru.","knRef":"Kniewald 1942, str. 374–375 (snimka 188) (OCR)"},"d5c1d046edad28be":{"t":"Ps 9, 11-12 i 13\nNek se ufaju u tebe svi koji poznaju ime tvoje, Gospodine, jer ne ostavljaš one koji te traže. Pjevajte Gospodinu na Sionu, jer nije zaboravio vapaj siromaha.","kn":"(Ps, 9, 11-13). Neka se uzdaju u Tebe svi, koji poznaju ime Tvoje, Gospodine, jer ne ostavljaš onih, koji Te traže. Pjevajte Gospodinu, koji nastava u Slonu, jer nije zaboravio moljenja ubogih.","knRef":"Kniewald 1942, str. 376–377 (snimka 189) (OCR)"},"7ccc3f388b76900e":{"t":"Pogledaj, Gospodine, na darove Crkve koja se moli i podaj da ih vjernici primaju na trajno posvećenje i spasenje.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Pogledaj, Gospodine, na darove Crkve, koja se moli i podaj, da bude na spasenje vjernih, što se ima sveudiljnim posvećivanjem primati, po G. n.","knRef":"Kniewald 1942, str. 376–377 (snimka 189) (OCR)"},"404159d2e4df1ef4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:","kn":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo Tebi, Gospodine sveti. Oče svemogući, vječni Bože, po Kristu, Gospotdiniu našemu, po kome veličanstvo Tvoje hvale anđeli, klanjaju Ti se gospodstva, tresu se vlasti. Nebesa Te i nebeske moći i blaženi serafini, zadružnim klicanjem zajedno slave. Zapovijedi, molimo, da se i naši glasovi združe s njihovima, smjernim isippvijedanjem govoreći:","knRef":"Kniewald 1942, str. 18–19 (snimka 10) (OCR)"},"ebd75d789d8f1181":{"t":"Lk 15, 10\nKažem vam: Anđeli se Božji raduju nad jednim grješnikom koji se obrati.","kn":"(Luk. 15, 10). Velim vam, radost je anđelima Božjima za jednoga grješnika, koji čini pokoru.","knRef":"Kniewald 1942, str. 376–377 (snimka 189) (OCR)"},"b97eb248f0278c9e":{"t":"<i>Pomolimo se</i>.\nTvoja nam sveta otajstva koja prinosimo, Gospodine, dala život i očišćene pripravila na neprestano milosrđe.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."}}});
